SELECT
    CAST(SUM(population) AS BIGINT) AS population
FROM full_2020
WHERE month = '2019-06'
  AND country = 'SAU'
  AND type = 'total_population'
  AND ST_Within(
      ST_Point(longitude, latitude),
      ST_Polygon('POLYGON ((49.6676533 26.4200567,49.6017438 25.8777249,49.6566684 25.6897906,49.8104573 25.5015594,49.9093215 25.3428196,50.0191707 25.2832384,50.0631104 25.3825242,50.1509898 25.5412116,50.2608389 25.5907585,50.4585675 25.6204768,50.5574317 25.798631,50.5354619 26.0949599,50.524477 26.1837129,50.2937937 26.242844,50.0081858 26.2132822,49.8653819 26.3708582,49.7775025 26.4003798,49.6676533 26.4200567))')
  );
